// ========== 6. 窗口管理优化 ==========
// 6.1 及时释放窗口引用，防止内存泄漏
const windowMap = new Map()

function createWindow(id) {
  const win = new BrowserWindow({...})
  windowMap.set(id, win)

  win.on('closed', () => {
    windowMap.delete(id) // 重要: 移除引用
  })

  return win
}

// 6.2 隐藏非活动窗口而不是销毁
// （如果用户会频繁切换）
function hideWindow(win) {
  win.hide() // 隐藏，不销毁，下次显示更快
}

function showWindow(win) {
  win.show()
}

